SELECT * FROM customer limit 20
--1. What is the total revenue generated by male vs. female customers?
SELECT gender, SUM(purchase_amount) AS revenue
FROM customer
GROUP BY gender;

--2. Which customers used a discount but still spent more than the average purchase amount?
SELECT customer_id, purchase_amount
FROM customer
WHERE (discount_applied = 'Yes') AND 
purchase_amount >(
SELECT AVG(purchase_amount) 
FROM customer
);

--3. Which are the top five products with highest average review rating?
SELECT item_purchased, ROUND(AVG(review_rating)::numeric,2) AS avg_product_rating
FROM customer
GROUP BY item_purchased
ORDER BY AVG(review_rating) DESC
LIMIT 5;

--4. Compare the average purchase amounts between Standard and Express Shipping.

SELECT shipping_type, ROUND(AVG(purchase_amount)::numeric,2)
FROM customer
WHERE shipping_type IN ('Standard', 'Express')
GROUP BY shipping_type;

--5. Do subscribed customers spend more? Compare average spend and total revenue between subscribers and non subscribers.

SELECT subscription_status,
COUNT(customer_id) AS total_customers,
ROUND(AVG(purchase_amount)::numeric,2) AS avg_spend,
ROUND(SUM(purchase_amount)::numeric,2) AS total_revenue
FROM customer
GROUP BY subscription_status
ORDER BY total_revenue DESC, avg_spend DESC;

--6. Which 5 products rely heavily on discounts to sell?
SELECT item_purchased,
((SUM(
CASE WHEN discount_applied = 'Yes' THEN 1 ELSE 0 END
)
)*100/ COUNT (*) ) AS bought_when_discount
FROM customer
GROUP BY item_purchased
ORDER BY bought_when_discount DESC
LIMIT 5;

--7. Segment customers into New, Returning and Loyal based on their total number of previous purchases,
--and show the count of each segment.

WITH customer_type AS(
SELECT customer_id, previous_purchases,
CASE 
	WHEN previous_purchases = 1 THEN 'New'
	WHEN previous_purchases BETWEEN 2 AND 10 THEN 'Returning'
	ELSE 'Loyal'
	END AS customer_segment
FROM customer
)
SELECT customer_segment, 
		COUNT(*) AS customer_type_count
FROM customer_type
GROUP BY customer_segment
ORDER BY customer_type_count DESC;

--8. What are the top three most purchased products in each category?
WITH item_counts AS
(
SELECT 	category, 
		item_purchased,
		COUNT(customer_id) AS total_orders,
		DENSE_RANK() OVER (PARTITION by category ORDER BY COUNT(customer_id) DESC) AS item_rank
FROM customer
GROUP BY category, item_purchased
)
SELECT category, item_purchased, total_orders, item_rank
FROM item_counts
WHERE item_rank<=3;


--9. Are customers who are repeat buyers(more than 5 purchases) also likely to subscribe?

SELECT subscription_status,
COUNT(customer_id) AS repeat_buyers
FROM customer
WHERE (previous_purchases > 5)
GROUP BY subscription_status;

--10. What is the revenue contribution of each age group?

SELECT age_group,
SUM(purchase_amount) AS total_revenue
FROM customer
GROUP BY age_group
ORDER BY total_revenue DESC;